import type { TFunction } from 'i18next';

/** Translate only labels generated by the frontend; keep unknown API text intact. */
export function translateMatchingText(value: string, t: TFunction) {
  if (value === '시간·거리 모두 일치') {
    return t('common.timeAndDistanceMatch');
  }
  if (value === '근무 시간 일치') {
    return t('matching.timeMatch');
  }
  if (value === '희망 거리') {
    return t('matching.distanceMatch');
  }
  if (value === '근무 시간 일치 · 희망 거리') {
    return `${t('matching.timeMatch')} · ${t('matching.distanceMatch')}`;
  }

  return value;
}
